### Step 1: Set Up Redux Toolkit for Your Project

First, you'll need to set up a store with `configureStore` from `@reduxjs/toolkit`. Create a file named `store.js`:

```javascript
import { configureStore } from '@reduxjs/toolkit';
import cartSlice from './cartSlice';

const store = configureStore({
  reducer: {
    cart: cartSlice.reducer,
  },
});

export default store;
export * from './cartSlice';
```

### Step 2: Create Cart Slice

In `cartSlice.js`, create your cart state and its corresponding actions:

```javascript
import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  items: [],
};

const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem(state, action) {
      state.items.push(action.payload);
    },
    removeItem(state, action) {
      state.items = state.items.filter((item) => item.id!== action.payload.id);
    },
  },
});

export const { addItem, removeItem } = cartSlice.actions;
export default cartSlice.reducer;
```

