    removeProduct(state, action) {
      state.items = state.items.filter((product) => product.id!== action.payload.id);
    },
    reset() {
      return initialState;
    },
  },
});

export const { addProduct, removeProduct, reset } = cartSlice.actions;
export default cartSlice.reducer;
