```jsx
const Cart = () => {
  const items = useSelector(state => state.cart.items);
  const addItem = useDispatch().cart.addItem;
  const removeItem = useDispatch().cart.removeItem;

  return (
    <div>
      <h2>Cart Total: ${items.reduce((acc, item) => acc + item.price * item.quantity, 0)}</h2>
      <ul>
        {items.map(item => (
          <li key={item.id}>
            <img src={item.image} />
            <span>{item.name}</span>
            <button onClick={() => removeItem(item.id)}>×</button>
            <input
              type="number"
              value={item.quantity}
              onChange={e => addItem(item.id, item.price, e.target.value)}
            />
          </li>
        ))}
      </ul>
    </div>
  );
};
```

