```sql
CREATE TABLE orders (
    id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    user_id INT NOT NULL,
    status VARCHAR(255) NOT NULL CHECK (status IN ('pending','shipped', 'delivered', 'canceled')),
    total DECIMAL(10, 2) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id)
);

CREATE UNIQUE INDEX orders_user_id_unique ON orders (user_id);

CREATE INDEX orders_status_index ON orders (status);
CREATE INDEX orders_created_at_index ON orders (created_at);

CREATE TABLE order_items (
    id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    order_id INT NOT NULL,
    product_id INT NOT NULL,
    quantity INT NOT NULL CHECK (quantity > 0),
    unit_price DECIMAL(10, 2) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (order_id) REFERENCES orders(id),
    FOREIGN KEY (product_id) REFERENCES products(id)
);

CREATE UNIQUE INDEX order_items_order_id_product_id_unique ON order_items (order_id, product_id);
CREATE INDEX order_items_order_id_index ON order_items (order_id);
CREATE INDEX order_items_product_id_index ON order_items (product_id);
```

Some notes:

*   I used `DECIMAL(10, 2)` for monetary fields to limit precision.
*   Check constraints ensure that order and item quantities are positive and status is within a valid set.
*   Foreign keys are used to link orders with users and items with products. Unique indexes on composite columns ensure a product can't be ordered multiple times within a single order.
*   Indexes on frequently queried columns like status and created_at speed up order retrieval.
